def read_lines(text):
    for line in text.split("\n"):
        stripped = line.strip()
        if stripped:
            yield stripped


def filter_comments(lines):
    for line in lines:
        if not line.startswith("#"):
            yield line


def parse_ints(lines):
    for line in lines:
        yield int(line)


def pipeline(text):
    lines = read_lines(text)
    filtered = filter_comments(lines)
    numbers = parse_ints(filtered)
    return sum(numbers)
